using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollments = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Description = "Exploration of abstract structures, quantities, and spatial relationships." },
            new() { Id = 3, Name = "English", Description = "Analysis of literature, rhetoric, and written communication." },
            new() { Id = 4, Name = "Physics", Description = "Investigation of matter, energy, and the fundamental forces of nature." },
            new() { Id = 5, Name = "History", Description = "Examination of past events, societies, and cultural developments." }
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = 1, Title = "Introduction to Programming", Description = "Fundamentals of programming using Python. Covers variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentId = 1, InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen holds a PhD from MIT and has 12 years of experience teaching introductory CS courses. Her research focuses on CS education and programming language design.", IsFeatured = true },
            new() { Id = 2, Title = "Data Structures", Description = "Study of fundamental data structures including arrays, linked lists, trees, graphs, and hash tables. Emphasis on algorithm analysis and implementation.", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", DepartmentId = 1, InstructorName = "Dr. James Rodriguez", InstructorBio = "Dr. Rodriguez specializes in algorithm optimization and has published extensively on graph algorithms. He previously worked at Google Research.", IsFeatured = true },
            new() { Id = 3, Title = "Operating Systems", Description = "Principles of operating system design including process management, memory allocation, file systems, and concurrency.", Credits = 4, Schedule = "Mon/Wed 2:00–3:15 PM", DepartmentId = 1, InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen holds a PhD from MIT and has 12 years of experience teaching introductory CS courses. Her research focuses on CS education and programming language design.", IsFeatured = false },

            // Mathematics
            new() { Id = 4, Title = "Linear Algebra", Description = "Vectors, matrices, linear transformations, eigenvalues, and applications to computer graphics and data science.", Credits = 3, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", DepartmentId = 2, InstructorName = "Dr. Maria Gonzalez", InstructorBio = "Dr. Gonzalez is an award-winning educator with expertise in applied mathematics. She has authored two widely-used textbooks on linear algebra.", IsFeatured = true },
            new() { Id = 5, Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions with applications to physics and engineering.", Credits = 4, Schedule = "Tue/Thu 8:00–9:15 AM", DepartmentId = 2, InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim earned his doctorate from Princeton and has mentored over 50 graduate students. His research interests include differential equations and mathematical modeling.", IsFeatured = false },
            new() { Id = 6, Title = "Discrete Mathematics", Description = "Logic, sets, combinatorics, graph theory, and proof techniques essential for computer science.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", DepartmentId = 2, InstructorName = "Dr. Maria Gonzalez", InstructorBio = "Dr. Gonzalez is an award-winning educator with expertise in applied mathematics. She has authored two widely-used textbooks on linear algebra.", IsFeatured = false },

            // English
            new() { Id = 7, Title = "Composition and Rhetoric", Description = "Development of academic writing skills including argumentation, research methods, and critical analysis of texts.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", DepartmentId = 3, InstructorName = "Prof. Emily Watson", InstructorBio = "Professor Watson is a published novelist and essayist. She has taught writing at the university level for 15 years and directs the campus writing center.", IsFeatured = false },
            new() { Id = 8, Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present, exploring themes of identity, freedom, and social change.", Credits = 3, Schedule = "Mon/Wed 3:30–4:45 PM", DepartmentId = 3, InstructorName = "Dr. Michael Thompson", InstructorBio = "Dr. Thompson is a specialist in 20th-century American fiction. His book on the Harlem Renaissance received the National Book Critics Circle Award.", IsFeatured = true },
            new() { Id = 9, Title = "Creative Writing", Description = "Workshop-based course in fiction and poetry writing. Students develop original works and provide constructive peer feedback.", Credits = 3, Schedule = "Fri 2:00–4:45 PM", DepartmentId = 3, InstructorName = "Prof. Emily Watson", InstructorBio = "Professor Watson is a published novelist and essayist. She has taught writing at the university level for 15 years and directs the campus writing center.", IsFeatured = false },

            // Physics
            new() { Id = 10, Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly laboratory sessions with hands-on experiments.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM + Lab Thu 2:00–4:50 PM", DepartmentId = 4, InstructorName = "Dr. Alan Foster", InstructorBio = "Dr. Foster worked at CERN before joining academia. He brings real-world particle physics experience to undergraduate education.", IsFeatured = false },
            new() { Id = 11, Title = "Quantum Mechanics", Description = "Introduction to quantum theory including wave functions, the Schrödinger equation, and applications to atomic structure.", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", DepartmentId = 4, InstructorName = "Dr. Alan Foster", InstructorBio = "Dr. Foster worked at CERN before joining academia. He brings real-world particle physics experience to undergraduate education.", IsFeatured = true },
            new() { Id = 12, Title = "Electromagnetism", Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.", Credits = 4, Schedule = "Mon/Wed 9:00–10:15 AM", DepartmentId = 4, InstructorName = "Dr. Priya Patel", InstructorBio = "Dr. Patel's research in photonics has led to three patents. She is passionate about making complex physics concepts accessible to all students.", IsFeatured = false },

            // History
            new() { Id = 13, Title = "World Civilizations", Description = "Survey of major world civilizations from antiquity to 1500 CE, examining political, economic, and cultural developments.", Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", DepartmentId = 5, InstructorName = "Dr. Catherine Blake", InstructorBio = "Dr. Blake is an archaeologist and historian specializing in ancient Mediterranean civilizations. She has directed excavations in Greece and Turkey.", IsFeatured = false },
            new() { Id = 14, Title = "Modern European History", Description = "Europe from the French Revolution to the present, including industrialization, world wars, and the formation of the EU.", Credits = 3, Schedule = "Mon/Wed/Fri 2:00–2:50 PM", DepartmentId = 5, InstructorName = "Dr. William Harris", InstructorBio = "Dr. Harris is a Rhodes Scholar whose research focuses on 20th-century European diplomacy. He frequently consults for historical documentaries.", IsFeatured = false },
            new() { Id = 15, Title = "The American Civil War", Description = "In-depth study of the causes, course, and consequences of the American Civil War and Reconstruction era.", Credits = 3, Schedule = "Tue/Thu 3:30–4:45 PM", DepartmentId = 5, InstructorName = "Dr. Catherine Blake", InstructorBio = "Dr. Blake is an archaeologist and historian specializing in ancient Mediterranean civilizations. She has directed excavations in Greece and Turkey.", IsFeatured = false }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
            query = query.Where(c =>
                c.Title.Contains(search, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(search, StringComparison.OrdinalIgnoreCase));

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public void SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        _enrollments.Add(request);
    }

    public List<Course> GetAllCourses() => _courses;
}

