@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService CatalogService

@{
    var course = CatalogService.GetCourse(Id);
    var department = course is not null ? CatalogService.GetDepartment(course.DepartmentId) : null;
}

